steps.starter:
// Lines that start with // are notes for people. The app skips them.
// Your own copy of the Beginner preset. By the end of this lesson it matches
// the Intermediate preset: the rules every run without a script uses.
script "Intermediate: built-in reward" for navigation v1

// navigation-starter sees eight rays, the way to the finish and the path hint.
brain navigation-starter

// This block runs for every runner, 30 times per second.
each tick {
  act(move: brain.move, turn: brain.turn)

  // Points for new ground: the whole way is worth 10.
  reward +10 * agent.progressGain
  // Ten points for crossing the line.
  reward +10 when agent.finished
}

// This block runs once per generation and breeds the next brains from the best.
each generation {
  speciate(target: 8)
  select(top: 20%)
  breed(crossover: 0.75, mutate: { weights: 0.8, addConnection: 0.05, addNode: 0.03, toggle: 0.01 })
  keepChampions()
}

